import {
    computed,
    effect,
    inject,
    Injectable,
    resource,
    signal,
    untracked,
} from '@angular/core';
import {
    alignDateToBookableHours,
    AsyncHandler,
    BookableHoursRange,
    BookingRuleset,
    currentUser,
    getAllDayTimeRange,
    i18n,
    isWithinBookableHours,
    notifyError,
    notifySuccess,
    rulesForResource,
    SettingsService,
    StaffUser,
    user_group_names,
    ViewAction,
    ViewerFeature,
    ViewerStyles,
} from '@placeos/common';
import { PlaceAsset } from '@placeos/ts-client';
import {
    addMinutes,
    endOfDay,
    getUnixTime,
    isSameDay,
    setHours,
    startOfDay,
    startOfMinute,
} from 'date-fns';

import { OrganisationService } from '@placeos/common';
import { queryParkingSpacesForZones } from 'libs/assets/src/lib/parking-assets.fn';
import { BookingFormService } from 'libs/bookings/src/lib/booking-form.service';
import {
    queryAllBookings,
    queryBookings,
} from 'libs/bookings/src/lib/bookings.fn';
import { ParkingService } from 'libs/bookings/src/lib/parking.service';
import { loadBookingRules } from './explore-booking-rules';
import { ExploreParkingInfoComponent } from './explore-parking-info.component';
import { DEFAULT_COLOURS } from './explore-spaces.service';
import { ExploreStateService } from './explore-state.service';

export type ParkingSpace = PlaceAsset;

export interface ParkingOptions {
    enable_booking?: boolean;
    date?: number;
    all_day?: boolean;
    duration?: number;
    zones?: string[];
    host?: StaffUser;
    custom?: boolean;
    use_api?: boolean;
    user?: string;
}

type ParkingStatus = 'not-bookable' | 'busy' | 'pending' | 'free';

/** Map status of a parking space. Sets its colour and the text on its card. */
function parkingStatus(
    space: ParkingSpace,
    is_assigned: boolean,
    can_book: boolean,
): ParkingStatus {
    if (space.bookable === false) return 'not-bookable';
    if (!can_book) return 'busy';
    return is_assigned ? 'pending' : 'free';
}

@Injectable()
export class ExploreParkingService extends AsyncHandler {
    private _org = inject(OrganisationService);
    private _state = inject(ExploreStateService);
    private _settings = inject(SettingsService);
    private _bookings = inject(BookingFormService);
    private _parking = inject(ParkingService);

    private _options = signal<ParkingOptions>({});
    private _poll = signal<number>(0);

    private _building = this._org.active_building;
    private _active_levels = this._org.active_levels;
    private _parking_users = this._parking.users;
    private _assigned_space = this._parking.assigned_space;
    private _deny_parking_access = this._parking.deny_parking_access;
    private _booked_space = this._parking.booked_space;

    public readonly options = this._options.asReadonly();
    public on_book: (ParkingSpace) => Promise<void> = null;

    /** List of available parking levels for the active building */
    public readonly levels = computed(() =>
        this._active_levels().filter((_) => _.tags.includes('parking')),
    );

    private _booking_rules = resource({
        params: () => this._building() || undefined,
        loader: ({ params: bld }) => loadBookingRules(bld.id, 'parking'),
    });
    public readonly booking_rules = computed<BookingRuleset[]>(
        () => this._booking_rules.value() ?? [],
    );

    /** List of current bookings for the current map level */
    private _events = resource({
        params: () => ({
            is_public: this._state.options().is_public,
            level_id: this._state.level()?.id,
            date: this._options().date,
            all_day: this._options().all_day,
            duration: this._options().duration,
            poll: this._poll(),
        }),
        loader: ({
            params: { is_public, level_id, date, all_day, duration },
        }) => {
            if (is_public || !level_id) return Promise.resolve([]);
            const time = date ?? Date.now();
            const hours = this._bookableHours();
            const day = getAllDayTimeRange(time, '', hours?.start, hours?.end);
            // Without all day or a duration, look 15 minutes back and 30 forward
            const start = all_day
                ? day.date
                : duration
                  ? time
                  : addMinutes(time, -15);
            const end = all_day
                ? day.date_end
                : addMinutes(time, duration || 30);
            return queryAllBookings({
                period_start: getUnixTime(start),
                period_end: getUnixTime(end),
                type: 'parking',
                zones: level_id,
                rejected: false,
            }).catch(() => []);
        },
    });
    /** List of current bookings for the current map level */
    public readonly events = computed(() => this._events.value() ?? []);

    /** Any event that the selected user has for the current date */
    private _user_events = resource({
        params: () => ({
            date: this._options().date,
            user: this._options().user,
        }),
        loader: ({ params: { date, user } }) =>
            queryBookings({
                period_start: getUnixTime(startOfDay(date || Date.now())),
                period_end: getUnixTime(endOfDay(date || Date.now())),
                type: 'parking',
                email: user || currentUser()?.email,
            }).catch(() => []),
    });
    /** Any event that the selected user has for the current date */
    public readonly user_events = computed(
        () => this._user_events.value() ?? [],
    );

    /** List of parking spaces for the active building */
    private _spaces = resource({
        params: () => {
            const levels = this.levels();
            return levels.length ? levels.map((l) => l.id) : undefined;
        },
        loader: ({ params: zones }) =>
            queryParkingSpacesForZones(zones).catch(() => [] as ParkingSpace[]),
    });
    /** List of parking spaces for the active building */
    public readonly spaces = computed<ParkingSpace[]>(
        () => this._spaces.value() ?? [],
    );

    public readonly active_spaces = computed(() => {
        const level = this._state.level();
        return level ? this.spaces().filter((_) => _.zone_id === level.id) : [];
    });

    private _users: Record<string, string> = {};
    private _plate_numbers: Record<string, string> = {};

    private _available_spaces = signal<ParkingSpace[]>([]);
    /** Available parking spaces for the current level and date */
    public readonly available_spaces = this._available_spaces.asReadonly();

    constructor() {
        super();
        effect(() => {
            const events = this.events();
            const spaces = this.active_spaces();
            const users = this._parking_users();
            const rules = this.booking_rules();
            const { date } = this._options();
            user_group_names();
            untracked(() => {
                // Build lookups once, not once for each space
                const event_by_space = new Map<
                    string,
                    (typeof events)[number]
                >();
                for (const e of events) {
                    if (!e.rejected && !event_by_space.has(e.asset_id)) {
                        event_by_space.set(e.asset_id, e);
                    }
                }
                const user_by_email = new Map<string, (typeof users)[number]>();
                for (const u of users) {
                    const email = u.email.toLowerCase();
                    if (!user_by_email.has(email)) user_by_email.set(email, u);
                }
                const available = spaces.filter((space) => {
                    const event = event_by_space.get(space.id);
                    const level = this._org.levelWithID([space.zone_id]);
                    const assigned = `${
                        event?.user_email || space.assigned_to || ''
                    }`.toLowerCase();
                    const user = user_by_email.get(assigned);
                    const is_restricted = rulesForResource(
                        {
                            date: date || Date.now(),
                            duration: 60,
                            host: currentUser(),
                            resource: {
                                id: space.id,
                                zones: [level?.parent_id, level?.id],
                            },
                        },
                        rules,
                    )?.hidden;
                    this._users[space.id] = assigned;
                    this._plate_numbers[space.id] =
                        event?.extension_data?.plate_number ||
                        user?.plate_number ||
                        undefined;
                    return !event && !is_restricted && space.bookable !== false;
                });
                this._available_spaces.set(available);
                this._updateParkingSpaces(spaces, available);
            });
        });
        this.setOptions({
            enable_booking:
                this._settings.get('app.parking.enable_maps') !== false,
        });
    }

    public startPolling() {
        this.interval('poll', () => this._poll.set(Date.now()), 10 * 1000);
        this._poll.set(Date.now());
        return () => this.stopPolling();
    }

    public stopPolling() {
        this.clearInterval('poll');
    }

    public setOptions(options: Partial<ParkingOptions>) {
        this._options.update((value) => ({ ...value, ...options }));
    }

    /** Bookable hours for parking, or for all bookings when parking has none */
    private _bookableHours(): BookableHoursRange | null {
        return (
            this._settings.get('app.parking.bookable_hours') ||
            this._settings.get('app.bookings.bookable_hours') ||
            null
        );
    }

    /** Set the map styles, info cards and booking actions of the spaces */
    private _updateParkingSpaces(
        spaces: ParkingSpace[],
        available: ParkingSpace[],
    ) {
        const styles: ViewerStyles = {};
        const features: ViewerFeature[] = [];
        const actions: ViewAction[] = [];
        const colours = this._settings.get('app.explore.colors') || {};
        const options = this._options();
        const available_ids = new Set(available.map((_) => _.id));
        const app_name = this._settings.app_name.toLowerCase();
        const is_workplace =
            app_name.includes('workplace') || app_name.includes('staff');
        for (const space of spaces) {
            const can_book = available_ids.has(space.id);
            const is_assigned = is_workplace ? false : !!space.assigned_to;
            const id = space.map_id || space.id;
            const status = parkingStatus(space, is_assigned, can_book);
            styles[`#${id}`] = {
                fill:
                    colours[`parking-${status}`] ||
                    colours[`${status}`] ||
                    DEFAULT_COLOURS[`${status}`],
                opacity: 0.6,
            };
            features.push({
                location: `${id}`,
                content: ExploreParkingInfoComponent,
                z_index: 20,
                hover: true,
                data: {
                    ...space,
                    user: this._users[space.id],
                    plate_number: this._plate_numbers[space.id],
                    status:
                        status === 'pending' && is_assigned
                            ? 'reserved'
                            : status,
                },
            });
            if (!can_book) continue;
            actions.push({
                id,
                action: 'click',
                priority: 10,
                callback: () => this._bookSpace(space, status),
            });
        }
        this._state.setActions(
            'parking',
            options.enable_booking ? actions : [],
        );
        this._state.setStyles('parking', styles);
        this._state.setFeatures('parking', features);
    }

    /**
     * Book a space that the user clicked on the map.
     * Uses `on_book` when it is set. Otherwise checks that the user can book
     * the space, then opens the booking form for it.
     */
    private async _bookSpace(space: ParkingSpace, status: ParkingStatus) {
        if (this.on_book) {
            await this.on_book(space);
            this._poll.set(Date.now());
            return;
        }
        const error = this._bookingError(space, status);
        if (error) return notifyError(error);
        this._bookings.newForm('parking');
        this._bookings.setOptions({ type: 'parking' });
        const options = this._options();
        const bookable_hours = this._bookableHours();
        if (
            bookable_hours &&
            !this._settings.get('app.parking.allow_time_changes') &&
            !isWithinBookableHours(Date.now(), bookable_hours)
        ) {
            return notifyError(i18n('EXPLORE.OUTSIDE_BOOKABLE_HOURS'));
        }
        const user = options.host || currentUser();
        const user_email = user?.email;
        const zone =
            this._org.levelWithID([
                space.zone_id ||
                    (space as ParkingSpace & { zone?: string }).zone,
            ]) || this._state.active_level;
        let date =
            !options.date || isSameDay(options.date, Date.now())
                ? startOfMinute(Date.now()).valueOf()
                : setHours(options.date, 8).valueOf();
        if (bookable_hours) {
            date = alignDateToBookableHours(date, bookable_hours);
        }
        this._bookings.model.update((m) => ({
            ...m,
            resources: [space],
            asset_id: space.id,
            asset_name: space.name,
            date,
            duration: 11 * 60,
            all_day: true,
            map_id: space?.map_id || space?.id,
            description: space.name,
            user,
            user_email,
            booking_type: 'parking',
            zones: [
                this._org.organisation.id,
                this._org.region?.id,
                zone?.parent_id,
                zone?.id,
            ],
        }));
        await this._bookings.confirmPost().catch((e) => {
            if (e === 'User cancelled') throw e;
            notifyError(
                i18n('EXPLORE.PARKING_BOOKING_ERROR', {
                    name: space.name || space.id,
                    error: e.message || e.error || e,
                }),
            );
            throw e;
        });
        notifySuccess(
            i18n('EXPLORE.PARKING_BOOKING_SUCCESS', {
                name: space.name || space.id,
            }),
        );
        this.timeout('poll', () => this._poll.set(Date.now()), 1000);
    }

    /** Message that tells why the user cannot book the space, or null */
    private _bookingError(space: ParkingSpace, status: ParkingStatus) {
        if (this._deny_parking_access()) {
            const space_zone = this._org.levelWithID([space.zone_id]);
            return i18n('EXPLORE.PARKING_PERMISSIONS_ERROR', {
                name: space_zone?.display_name || space_zone?.name,
            });
        }
        if (this._assigned_space() && this._booked_space()) {
            return i18n('EXPLORE.PARKING_ASSIGNED_ERROR', {
                name: space.name || space.id,
            });
        }
        if (this._booked_space()) {
            return i18n('EXPLORE.PARKING_EXISTING_ERROR');
        }
        if (status !== 'free') {
            return i18n('EXPLORE.UNAVAILABLE_ERROR', {
                name: space.name || 'Parking Space',
            });
        }
        // The placeholder user has no groups before the user loads
        const user_groups = currentUser()?.groups || [];
        if (
            space.place_groups?.length &&
            !space.place_groups.find((_) => user_groups.includes(_))
        ) {
            return i18n('EXPLORE.NOT_ALLOWED_ERROR', { name: space.name });
        }
        return null;
    }
}
